import { IconPlus } from '@hawkins/assets';
import { Button, Loader, Stack, Text } from '@hawkins/components';
import { ButtonRenderer, Table, Toolbar, type TypeColumn, type TypeEditInfo } from '@hawkins/table';
import { Dimensions } from '@hawkins/variables';
import type React from 'react';
import { useCallback, useState } from 'react';
import { NewAssetModal } from './NewAssetModal';
import { useToolkitAssetDelete, useToolkitAssetUpload, useToolkitPlatforms } from './data';
import type { NewAssetDetails, ToolkitAsset } from './types';

interface AssetTableProps {
    assets: ToolkitAsset[];
    name: string;
    version: string;
    upload?: boolean;
    onValidateForm: (key?: string[]) => boolean;
    onAdd: (asset: ToolkitAsset) => void;
    onDelete?: (asset: ToolkitAsset) => void;
    onUpdate?: (asset: ToolkitAsset) => void;
}

export function AssetTable({ assets, name, version, upload, onValidateForm, onAdd, onDelete, onUpdate }: AssetTableProps) {
    const [showAddAssetModal, setShowAddAssetModal] = useState(false);
    const [assetUploadProgress, setAssetUploadProgress] = useState(0);
    const { data: platforms = [] } = useToolkitPlatforms();
    const { mutate: assetUpload } = useToolkitAssetUpload();
    const { mutate: assetDelete, isPending: isDeletingAsset } = useToolkitAssetDelete();

    function handleAddAsset(asset: NewAssetDetails) {
        setShowAddAssetModal(false);
        assetUpload({
            asset,
            onProgress: p => {
                setAssetUploadProgress(p);
            },
            onSuccess: ({ url }) => {
                setAssetUploadProgress(0);
                onAdd({
                    name: asset.name,
                    version: asset.version,
                    hash: asset.hash,
                    bin: asset.bin,
                    platform: platforms.find(plt => plt.name === asset.platform)!,
                    url,
                    size: asset.file.size,
                });
            },
        });
    }

    const onEditComplete = useCallback(
        ({ value, columnId, rowIndex }: TypeEditInfo) => {
            const updatedAsset = { ...assets[rowIndex], [columnId]: value };
            onUpdate?.(updatedAsset);
        },
        [assets, onUpdate],
    );

    const assetColumns: TypeColumn[] = [
        {
            name: 'platform',
            header: 'Platform',
            flex: 1,
            render: ({ data }: { data: ToolkitAsset }) => data.platform.displayName,
        },
        {
            name: 'bin',
            header: 'Bin Path',
            flex: 1,
            editable: true,
            renderEditor: (props: {
                value: string;
                onChange: (value: string) => void;
                onComplete?: () => void;
                onCancel?: () => void
            }) => {
                const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
                    if (e.key === 'Enter') {
                        e.preventDefault();
                        props.onComplete && props.onComplete();
                    } else if (e.key === 'Escape') {
                        e.preventDefault();
                        props.onCancel && props.onCancel();
                    }
                };

                const handleBlur = () => {
                    props.onComplete && props.onComplete();
                };

                return (
                    <input
                        type="text"
                        value={props.value || ''}
                        onChange={(e) => props.onChange(e.target.value)}
                        onKeyDown={handleKeyDown}
                        onBlur={handleBlur}
                        style={{
                            width: '100%',
                            padding: '8px',
                            border: '1px solid var(--hawkins-colors-border-primary)',
                            borderRadius: '4px',
                            backgroundColor: 'var(--hawkins-colors-background-primary)',
                            color: 'var(--hawkins-colors-foreground-primary)',
                            fontSize: '14px',
                        }}
                        autoFocus
                    />
                );
            },
        },
        {
            name: 'size',
            header: 'Size',
            flex: 1,
            render: ({ data }: { data: ToolkitAsset }) => `${Math.round(data.size / (1024 * 1024))} MB`,
        },
        {
            name: 'updatedDate',
            header: 'Updated Date',
            flex: 1,
        },
        {
            name: 'url',
            header: 'Url',
            flex: 1,
        },
        {
            name: 'actionRemove',
            header: '',
            flex: 1,
            textAlign: 'center',
            render: ButtonRenderer<string, ToolkitAsset>({
                text: 'Remove',
                variant: 'primary-destructive',
                compact: true,
                onClick: ({ event, value, data }) => {
                    assetDelete(data);
                    onDelete && onDelete(data);
                },
            }),
        },
    ];

    function handleAddAssetModalClose() {
        setShowAddAssetModal(false);
    }

    function handleAddAssetClick() {
        if (!onValidateForm(['extensionName', 'extensionVersion'])) {
            return;
        }
        setShowAddAssetModal(true);
    }

    const platformOptions = platforms.map(plt => ({ value: plt.name, label: plt.displayName }));
    const isLoading = isDeletingAsset;

    return (
        <>
            {assetUploadProgress ? (
                <Stack>
                    <Loader
                        variant='linear'
                        state={assetUploadProgress >= 100 ? 'indeterminate' : 'determinate'}
                        value={assetUploadProgress}
                    />
                    <Text variant='body' level={0}>
                        {`Uploading... ${assetUploadProgress}%`}
                    </Text>
                </Stack>
            ) : null}
            <Table
                loading={isLoading}
                disableTableHeaderTooltip
                rowHeight='compact'
                idProperty='uuid'
                editable
                columns={assetColumns}
                dataSource={assets}
                onEditComplete={onEditComplete}
                style={{ width: '100%' }}
            >
                <Toolbar
                    left={
                        <Stack gap={Dimensions.Space10} orientation='horizontal'>
                            <Button compact icon={IconPlus} onClick={handleAddAssetClick}>
                                Add Asset
                            </Button>
                        </Stack>
                    }
                />
            </Table>
            <NewAssetModal
                platformOptions={platformOptions}
                name={name}
                version={version}
                show={showAddAssetModal}
                upload={upload}
                onClose={handleAddAssetModalClose}
                onAdd={handleAddAsset}
            />
        </>
    );
}
