import type {
    Notification,
    NotificationPersistence,
    NotificationTarget,
    NotificationType,
    NotificationVariant,
    PlatformType
} from '@gsm-app/hooks/useNotifications';
import { Input } from '@gsm-common/components/Input';
import { IconCircleI } from '@hawkins/assets';
import {
    Accordion,
    AccordionDetails,
    AccordionSummary,
    Button,
    ButtonGroup,
    DatePickerDropdown,
    Dropdown,
    type DropdownOption,
    FormGroup,
    Heading,
    Modal,
    ModalBody,
    ModalFooter,
    ModalHeader,
    Stack,
    Text,
    Tooltip
} from '@hawkins/components';
import { Colors, Dimensions } from '@hawkins/variables';
import { type ChangeEvent, useEffect, useState } from 'react';
import styles from './NotificationsModal.module.css';

const notificationTypeOptions = [
    { label: 'Banner', value: 'BANNER' },
    { label: 'Modal', value: 'MODAL' },
    { label: 'Toaster', value: 'TOASTER' },
    { label: 'Sidebar', value: 'SIDEBAR' },
];
const notificationVariantOptions = [
    { label: 'Regular', value: 'REGULAR' },
    { label: 'Error', value: 'ERROR' },
    { label: 'Success', value: 'SUCCESS' },
    { label: 'Warning', value: 'WARNING' },
];

const notificationPersistenceOptions = [
    { label: 'Transient', value: 'TRANSIENT' },
    { label: 'Permanent', value: 'PERMANENT' },
    { label: 'Clearable', value: 'CLEARABLE' },
];

const notificationTargetPlatformOptions = [
    { label: 'Development Portal', value: 'ncgtportal' },
    { label: 'Toolkit App', value: 'ncgt-cli' },
];

interface NewNotificationModalProps {
    notification?: Notification;

    show: boolean;
    onClose: () => void;
    onCreate: (data: Notification) => void;
    onEdit: (data: Notification) => void;
}

export function NewNotificationModal(props: NewNotificationModalProps) {
    const { show, notification, onClose, onCreate, onEdit } = props;
    const today = new Date().toString();
    let defaultEndDate = new Date(today);
    defaultEndDate.setDate(defaultEndDate.getDate() + 14);
    const defaultEnd = defaultEndDate.toISOString().split('T')[0];

    const defaultTitle = notification?.title ? notification?.title : '';
    const [title, setTitle] = useState<string>(defaultTitle);
    const [markup, setMarkup] = useState<string>(notification?.markup || '');
    const [type, setType] = useState<NotificationType>(notification?.type || 'BANNER');
    const [variant, setVariant] = useState<NotificationVariant>(notification?.variant || 'REGULAR');
    const [persistence, setPersistence] = useState<NotificationPersistence>(notification?.persistence);
    const [endDate, setEndDate] = useState<string>(notification?.endDate || defaultEnd);
    const [startDate, setStartDate] = useState<string>(notification?.startDate || '');
    const [target, setTarget] = useState<NotificationTarget | undefined>(notification?.target);

    function onCloseModal() {
        onClose();
        resetForm();
    }

    // Update the notification values after the modal is mounted
    useEffect(() => {
        if (notification) {
            setTitle(notification.title);
            setMarkup(notification.markup);
            setType(notification.type);
            setVariant(notification.variant);
            setPersistence(notification.persistence);
            setTarget(notification.target);
            notification.startDate && setStartDate(notification.startDate);
            notification.endDate && setEndDate(notification.endDate);
        }
    }, [notification]);

    function onSubmit() {
        const notificationData: Notification = {
            uuid: notification?.uuid || '',
            title,
            markup,
            type,
            variant,
            persistence,
            endDate,
            startDate,
            target: target?.partner || target?.platform || target?.version ? target : undefined,
        };

        // Create a new notification
        if (!notification) {
            onCreate(notificationData);
        } else {
            onEdit(notificationData);
        }
        resetForm();
    }

    function resetForm() {
        setTitle('');
        setMarkup('');
        setType('BANNER');
        setVariant('REGULAR');
        setStartDate('');
        setEndDate(defaultEnd);
        setTarget(undefined);
    }

    const typeOption = notificationTypeOptions.find(option => {
        return option.value === type;
    });

    const variantOption = notificationVariantOptions.find(option => {
        return option.value === variant;
    });

    const persistenceOption = notificationPersistenceOptions.find(option => {
        return option.value === persistence;
    });

    const targetPlatformOption = notificationTargetPlatformOptions.find(option => {
        return option.value === target?.platform;
    });

    return (
        <Modal minWidth={Dimensions.Size448} open={show} onClose={onClose}>
            <ModalHeader>
                <Heading level={0}>New Notification</Heading>
            </ModalHeader>
            <ModalBody>
                <FormGroup>
                    <FormGroup>
                        <Input
                            label='Title'
                            required={type !== 'BANNER'}
                            requirementType={type !== 'BANNER' ? 'required-star' : undefined}
                            placeholder='Insert the notification title'
                            value={title}
                            onChange={(event: ChangeEvent<HTMLInputElement>) => {
                                setTitle(event.target.value);
                            }}
                            inputProps={{
                                max: 255,
                            }}
                        />
                        <Input
                            label='Markup'
                            required
                            multiline
                            rows={5}
                            rowsMax={8}
                            placeholder='Notification message'
                            value={markup}
                            onChange={(event: ChangeEvent<HTMLInputElement>) => {
                                setMarkup(event.target.value);
                            }}
                        />
                        <Dropdown
                            label='Type'
                            placeholder='How will the notification be presented?'
                            requirementType='required-star'
                            value={typeOption}
                            options={notificationTypeOptions}
                            onChange={(selectedOption: DropdownOption<string> | null) => {
                                setType(selectedOption?.value as NotificationType);
                            }}
                        />
                        <Dropdown
                            label='Variant'
                            placeholder='What kind of message?'
                            options={notificationVariantOptions}
                            value={variantOption}
                            onChange={(selectedOption: DropdownOption<string> | null) => {
                                setVariant(selectedOption?.value as NotificationVariant);
                            }}
                        />
                        {/* <Stack orientation="horizontal" layout={{ justifyItems: 'stretch'}}> */}
                        <Dropdown
                            label={
                                <Stack orientation='horizontal'>
                                    <Text colorVariant='faded'>Persistence</Text>
                                    <Tooltip
                                        description={[
                                            '',
                                            'Will remain across sessions',
                                            'Has a dismiss option',
                                            'Toasters will clear after a timeout',
                                        ]}
                                        label={[
                                            'Persistence determines whether the notification is dismissible and it persists across sessions',
                                            'Permanent',
                                            'Clearable',
                                            'Transient',
                                        ]}
                                    >
                                        <IconCircleI size='small' style={{ marginLeft: Dimensions.Space12 }} />
                                    </Tooltip>
                                </Stack>
                            }
                            placeholder='Should it persist across sessions?'
                            value={persistenceOption}
                            onChange={(selectedOption: DropdownOption<string> | null) => {
                                setPersistence(selectedOption?.value as NotificationPersistence);
                            }}
                            options={notificationPersistenceOptions}
                        />
                        <Accordion>
                            <AccordionSummary classes={{toggleIconButton: styles.targetButton, toggleIconContainer: styles.targetButtonContainer }} style={{ padding: `${Dimensions.Space8} ${Dimensions.Space0}`, backgroundColor: Colors.Transparent }} title='Target Data' toggleWithIconOnly/>
                            <AccordionDetails style={{ paddingLeft: Dimensions.Space0, paddingRight: Dimensions.Space0 }}>
                                <Dropdown
                                    label='Platform'
                                    placeholder='Select a target Platform'
                                    options={notificationTargetPlatformOptions}
                                    value={targetPlatformOption}
                                    style={{ marginBottom: Dimensions.Space16 }}
                                    onChange={(selectedOption: DropdownOption<string> | null) => {
                                        const updatedPlatform = { platform: selectedOption?.value as PlatformType };
                                        const updatedTarget = target ? { ...target, ...updatedPlatform } : updatedPlatform;
                                        setTarget(updatedTarget);
                                    }}
                                    clearable={true}
                                />
                                <Input
                                    label='Partner'
                                    placeholder='Target Partner ID'
                                    style={{ marginBottom: Dimensions.Space16 }}
                                    value={target?.partner}
                                    onChange={(event: ChangeEvent<HTMLInputElement>) => {
                                        const updatedPartner = { partner: event.target.value ? event.target.value : undefined };
                                        const updatedTarget = target ? { ...target, ...updatedPartner } : updatedPartner;
                                        setTarget(updatedTarget);
                                    }}
                                    inputProps={{
                                        max: 255,
                                    }}
                                />
                                <Input
                                    label='Version'
                                    placeholder='Target client version (e.g., 1.2.3)'
                                    style={{ marginBottom: Dimensions.Space8 }}
                                    value={target?.version}
                                    onChange={(event: ChangeEvent<HTMLInputElement>) => {
                                        const updatedVersion = { version: event.target.value ? event.target.value : undefined };
                                        const updatedTarget = target ? { ...target, ...updatedVersion } : updatedVersion;
                                        setTarget(updatedTarget);
                                    }}
                                    inputProps={{
                                        max: 20,
                                    }}
                                />
                            </AccordionDetails>
                        </Accordion>
                        {/* </Stack> */}
                        <DatePickerDropdown
                            inputProps={{ label: 'Start Date' }}
                            clearable
                            selected={startDate}
                            minSelectableDate={today}
                            maxSelectableDate={endDate}
                            onSelectedChange={(selected: any) => setStartDate(selected as string)}
                        />
                        <DatePickerDropdown
                            inputProps={{ label: 'End Date' }}
                            clearable
                            minSelectableDate={startDate || today}
                            selected={endDate}
                            onSelectedChange={(selected: any) => setEndDate(selected as string)}
                        />
                    </FormGroup>
                </FormGroup>
            </ModalBody>
            <ModalFooter>
                <ButtonGroup justifyContent='flex-end'>
                    <Button variant='secondary' onClick={onCloseModal}>
                        Close
                    </Button>
                    <Button onClick={onSubmit}>{!!notification ? 'Update' : 'Create'}</Button>
                </ButtonGroup>
            </ModalFooter>
        </Modal>
    );
}
