import { useModalOnClose } from '@gsm-app/hooks/useModalOnClose';
import { Input } from '@gsm-common/components/Input';
import {
    Button,
    ButtonGroup,
    Dropdown,
    type DropdownOption,
    FormGroup,
    Heading,
    Modal,
    ModalBody,
    ModalFooter,
    ModalHeader,
} from '@hawkins/components';
import { type ChangeEvent, useState } from 'react';
import { AssetTable } from './AssetTable';
import type { ToolkitAsset, ToolkitRelease } from './types';

type ReleaseChannelOptionType = DropdownOption<string>;

interface AddReleaseModalProps {
    channelOptions: ReleaseChannelOptionType[];
    show: boolean;
    onClose: () => void;
    onCreate: (data: ToolkitRelease) => void;
}

export function NewReleaseModal({ channelOptions, show, onClose, onCreate }: AddReleaseModalProps) {
    const [version, setVersion] = useState<string>('');
    const [notes, setNotes] = useState<string>('');
    const [selectedChannel, setSelectedChannel] = useState<ReleaseChannelOptionType | null>(null);
    const [assets, setAssets] = useState<ToolkitAsset[]>([]);

    function handleAddAssets(asset: ToolkitAsset) {
        setAssets(prevAssets => [...prevAssets, asset]);
    }

    function handleUpdateAsset(asset: ToolkitAsset) {
        setAssets(prevAssets => prevAssets.map(prevAsset => prevAsset.uuid === asset.uuid ? asset : prevAsset));
    }

    function handleVersionChange(event: ChangeEvent<HTMLInputElement>) {
        setVersion(event.target.value);
    }

    function handleNotesChange(event: ChangeEvent<HTMLInputElement>) {
        setNotes(event.target.value);
    }

    function handleChannelChange(selectedOption: ReleaseChannelOptionType | null) {
        setSelectedChannel(selectedOption);
    }

    function handleCloseClick() {
        resetForm();
        onClose();
    }

    function handleAddReleaseClick() {
        const newRelease = {
            version,
            notes,
            channel: {
                name: selectedChannel!.value,
                displayName: selectedChannel!.label,
            },
            assets,
            extensions: [],
        };
        onCreate(newRelease);
        resetForm();
    }

    function resetForm() {
        setVersion('');
        setNotes('');
        setSelectedChannel(null);
        setAssets([]);
    }

    const handleOnClose = useModalOnClose({ onClose });

    return (
        <Modal fullScreen open={show} onClose={handleOnClose}>
            <ModalHeader>
                <Heading level={0}>New Release</Heading>
            </ModalHeader>
            <ModalBody>
                <FormGroup>
                    <FormGroup>
                        <Dropdown
                            label='Channel'
                            placeholder='Select a release channel'
                            requirementType='required-star'
                            options={channelOptions}
                            value={selectedChannel}
                            onChange={handleChannelChange}
                        />
                        <Input
                            label='Version'
                            requirementType='required-star'
                            placeholder='Insert a version'
                            value={version}
                            onChange={handleVersionChange}
                            inputProps={{
                                pattern:
                                    '^([0-9]+).([0-9]+).([0-9]+)(?:-([0-9A-Za-z-]+(?:.[0-9A-Za-z-]+)*))?(?:+[0-9A-Za-z-]+)?$', // semver
                                autoComplete: 'off',
                                max: 50,
                            }}
                        />
                        <Input
                            label='Release Notes'
                            multiline
                            rows={5}
                            rowsMax={8}
                            placeholder='Release notes'
                            onChange={handleNotesChange}
                        />
                        <AssetTable
                            assets={assets}
                            name='ncgt-app'
                            version={version}
                            onValidateForm={() => true}
                            onAdd={handleAddAssets}
                            onUpdate={handleUpdateAsset}
                        />
                    </FormGroup>
                </FormGroup>
            </ModalBody>
            <ModalFooter>
                <ButtonGroup justifyContent='flex-end'>
                    <Button variant='secondary' onClick={handleCloseClick}>
                        Close
                    </Button>
                    <Button onClick={handleAddReleaseClick}>Create</Button>
                </ButtonGroup>
            </ModalFooter>
        </Modal>
    );
}
