import { IconMenu, IconPencil, IconPlus, IconTrashCan } from '@hawkins/assets';
import { Button, Chip, MenuItem, Stack } from '@hawkins/components';
import {
    BadgeRenderer,
    DatePickerEditor,
    DropdownEditor,
    DropdownFilter,
    HawkinsTableClassNames,
    MenuRenderer,
    Table,
    TextFilter,
    Toolbar,
    type TypeColumn,
    type TypeEditInfo,
} from '@hawkins/table';
import { Dimensions } from '@hawkins/variables';
import { useCallback, useState } from 'react';
import { EditExtensionModal } from './EditExtensionModal';
import { NewExtensionModal } from './NewExtensionModal';
import {
    useToolkitExtensionCreate,
    useToolkitExtensionDelete,
    useToolkitExtensions,
    useToolkitExtensionUpdate,
} from './data';
import type { ToolkitExtension, ToolkitRelease } from './types';
import { useFeature } from '@gsm-app/hooks/useFeature';

export enum ToolkitExtensionState {
    DRAFT = 'DRAFT',
    SCHEDULED = 'SCHEDULED',
    PUBLISHED = 'PUBLISHED',
}

const extensionStateOptions = Object.values(ToolkitExtensionState).map(state => ({ value: state, label: state }));

const renderExtensionDetails = ({ data, adminPageV2 }: { data: ToolkitExtension; adminPageV2: boolean }) => {
    return (
        <div style={{ padding: 20 }}>
            <h3>Extension details:</h3>
            <table>
                <tbody>
                    {Object.keys(data).filter(name => !(adminPageV2 && (name === 'state' || name === 'releaseScheduleDate'))).map((name, i) => {
                        let value = data[name];
                        if (Array.isArray(value)) {
                            if (value.every(item => typeof item === 'object')) {
                                // This is an array of objects. We'll represent each object with its JSON string.
                                if (name === 'assets') {
                                    // If this is the assets array, display the platform names in bullet point form
                                    value = value
                                        .map(item => item.platform && item.platform.name)
                                        .filter(Boolean)
                                        .map(platformName => <li key={platformName}>{platformName}</li>);
                                    value = <ul>{value}</ul>;
                                } else if (name === 'releases') {
                                    value = value
                                        .map(item => ({ version: item.version, state: item.state }))
                                        .filter(Boolean)
                                        .map(release => (
                                            <li key={release.version}>
                                                {release.version} [{release.state}]
                                            </li>
                                        ));
                                    value = <ul>{value}</ul>;
                                } else {
                                    value = value.map(item => JSON.stringify(item)).join(', ');
                                }
                            } else {
                                // This is an array of primitive values (numbers, strings, etc).
                                value = value.join(', ');
                            }
                        } else if (typeof value === 'object' && value !== null) {
                            // This is a single object.
                            value = JSON.stringify(value);
                        }
                        return (
                            <tr key={i}>
                                <td>{name}</td>
                                <td>{value}</td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
        </div>
    );
};

export function ExtensionTable({ releases }: { releases: ToolkitRelease[] }) {
    const { adminPageV2 } = useFeature();
    const { data: extensions = [], isFetching: isFetchingExtensions } = useToolkitExtensions();
    const { mutate: extensionCreate, isPending: isCreatingExtension } = useToolkitExtensionCreate();
    const { mutate: extensionUpdate, isPending: isUpdatingExtension } = useToolkitExtensionUpdate();
    const { mutate: extensionDelete, isPending: isDeletingExtension } = useToolkitExtensionDelete();
    const [expandedRows, setExpandedRows] = useState<{ [key: string]: boolean } | undefined>(undefined);
    const [collapsedRows, setCollapsedRows] = useState<{ [key: string]: boolean } | undefined>(undefined);
    const [currentExtension, setCurrentExtension] = useState<ToolkitExtension>();
    const [showAddExtensionModal, setShowAddExtensionModal] = useState(false);
    const [showEditExtensionModal, setShowEditExtensionModal] = useState(false);

    const extensionOptions = getExtensionNameOptions(extensions);

    const extensionColumns: TypeColumn[] = [
        {
            name: 'name',
            header: 'Name',
            textAlign: 'center',
            flex: 1,
            filterEditor: DropdownFilter({
                placeholder: 'Filter by name...',
                options: extensionOptions,
            }),
        },
        {
            name: 'version',
            header: 'Version',
            textAlign: 'center',
            flex: 1,
            filterEditor: TextFilter({
                placeholder: 'Filter by version...',
            }),
        },
        {
            name: 'platform',
            header: 'Platforms',
            flex: 1,
            render: ({ data }: { data: ToolkitExtension }) => {
                return (
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: Dimensions.Space4, alignItems: 'center' }}>
                        {data.assets.map(asset => {
                            return (
                                <Chip compact key={asset.platform.name}>
                                    {asset.platform.name}
                                </Chip>
                            );
                        })}
                    </div>
                );
            },
        },
        {
            name: 'state',
            header: 'State',
            textAlign: 'center',
            flex: 1,
            editable: true,
            render: BadgeRenderer<string, ToolkitExtension>({
                badgeProps: ({ value }) => {
                    if (value === ToolkitExtensionState.PUBLISHED) {
                        return {
                            color: 'COMPLETE',
                        };
                    } else if (value === ToolkitExtensionState.DRAFT) {
                        return {
                            color: 'IN_PROGRESS',
                        };
                    } else {
                        return {
                            color: 'UNKNOWN',
                        };
                    }
                },
            }),
            renderEditor: DropdownEditor({
                compact: true,
                dropdownProps: {
                    clearable: false,
                },
                options: extensionStateOptions,
            }),
            filterEditor: DropdownFilter({
                placeholder: 'Filter by state...',
                options: extensionStateOptions,
            }),
        },
        {
            name: 'publishedDate',
            header: 'Published Date',
            textAlign: 'center',
            flex: 1,
            render: ({ data }: { data: ToolkitExtension }) =>
                data.publishedDate ? new Date(data.publishedDate).toLocaleString() : '',
        },
        {
            name: 'releaseScheduleDate',
            header: 'Release Schedule Date',
            flex: 1,
            className: ({ data }: { data: ToolkitExtension }) =>
                data.state === ToolkitExtensionState.SCHEDULED && !data.releaseScheduleDate
                    ? HawkinsTableClassNames.ValidationError
                    : '',
            editable: (editValue, cellProps) => cellProps.data.state === ToolkitExtensionState.SCHEDULED,
            renderEditor: DatePickerEditor({
                compact: true,
                calendarProps: { pickerVariant: 'datetimepicker' },
            }),
        },
        // {
        //     name: 'createdDate',
        //     header: 'Created Date',
        //     textAlign: 'center',
        //     flex: 1,
        //     render: ({ data }: { data: ToolkitExtension }) => data.createdDate ? new Date(data.createdDate).toLocaleString() : '',
        // },
        {
            name: 'actions',
            textAlign: 'center',
            flex: 1,
            render: MenuRenderer<string, ToolkitExtension>({
                trigger: <Button variant='icon' compact icon={IconMenu} aria-label='trigger' />,
                menuItems: ({ data }) => {
                    return [
                        <MenuItem key='edit' label='Edit' icon={IconPencil} onClick={() => handleEditClick(data)} />,
                        <MenuItem
                            key='delete'
                            label='Delete'
                            icon={IconTrashCan}
                            onClick={() => handleDeleteClick(data)}
                        />,
                    ];
                },
            }),
        },
    ];

    const onExpandedRowsChange = useCallback(
        ({ expandedRows, collapsedRows }: { expandedRows: any; collapsedRows: any }) => {
            setExpandedRows(expandedRows);
            setCollapsedRows(collapsedRows);
        },
        [],
    );

    const onEditComplete = useCallback(
        async ({ value, columnId, rowIndex }: TypeEditInfo) => {
            const data = [...extensions];
            data[rowIndex][columnId] = value;
            extensionUpdate(data[rowIndex]);
        },
        [extensions],
    );

    function handleEditClick(extension: ToolkitExtension) {
        setCurrentExtension(extension);
        setShowEditExtensionModal(true);
    }

    function handleDeleteClick(extension: ToolkitExtension) {
        extensionDelete(extension);
    }

    function handleEditExtensionModalClose() {
        setShowEditExtensionModal(false);
        setCurrentExtension(undefined);
    }

    function handleAddExtensionModalClose() {
        setShowAddExtensionModal(false);
    }

    function handleCreateExtension(data: ToolkitExtension) {
        setShowAddExtensionModal(false);
        extensionCreate(data);
    }

    function handleNewExtensionClick() {
        setShowAddExtensionModal(true);
    }

    function handleUpdateExtension(extension: ToolkitExtension) {
        setShowEditExtensionModal(false);
        setCurrentExtension(undefined);
        extensionUpdate(extension);
    }

    const isLoading = isFetchingExtensions || isCreatingExtension || isUpdatingExtension || isDeletingExtension;

    const filteredColumns = adminPageV2
        ? extensionColumns.filter(col => col.name !== 'state' && col.name !== 'releaseScheduleDate')
        : extensionColumns;

    return (
        <div style={adminPageV2 ? { display: 'flex', flexDirection: 'column', flex: 1, marginTop: '10px' } : { marginTop: '10px' }}>
            <Table<ToolkitExtension>
                loading={isLoading}
                disableTableHeaderTooltip
                rowHeight={adminPageV2 ? 120 : 'xLarge'}
                idProperty='uuid'
                expandedRows={expandedRows}
                collapsedRows={collapsedRows}
                // @ts-expect-error
                onExpandedRowsChange={onExpandedRowsChange}
                rowExpandHeight={400}
                // @ts-expect-error
                renderRowDetails={(props) => renderExtensionDetails({ ...props, adminPageV2 })}
                columns={filteredColumns}
                dataSource={extensions}
                onEditComplete={onEditComplete}
                style={adminPageV2 ? { width: '100%', height: '100%' } : { width: '100%', minHeight: 500 }}
                defaultFilterValue={adminPageV2 ? [
                    { name: 'name', operator: 'inlist', type: 'select', value: null },
                    { name: 'version', operator: 'contains', type: 'string', value: null },
                ] : [
                    { name: 'name', operator: 'inlist', type: 'select', value: null },
                    { name: 'version', operator: 'contains', type: 'string', value: null },
                    { name: 'state', operator: 'inlist', type: 'select', value: null },
                ]}
            >
                <Toolbar
                    left={
                        <Stack gap={Dimensions.Space10} orientation='horizontal'>
                            <Button compact icon={IconPlus} onClick={handleNewExtensionClick}>
                                New Extension
                            </Button>
                        </Stack>
                    }
                />
            </Table>
            <NewExtensionModal
                releases={releases}
                extensionOptions={extensionOptions}
                show={showAddExtensionModal}
                onClose={handleAddExtensionModalClose}
                onCreate={handleCreateExtension}
            />
            {currentExtension && (
                <EditExtensionModal
                    releases={releases}
                    extensionOptions={extensionOptions}
                    show={showEditExtensionModal}
                    onClose={handleEditExtensionModalClose}
                    onUpdate={handleUpdateExtension}
                    currentExtension={currentExtension}
                />
            )}
        </div>
    );
}

function getExtensionNameOptions(data: ToolkitExtension[]) {
    let uniqueNames = new Set<string>();

    // Iterate over the data and add each name to the Set
    for (let item of data) {
        uniqueNames.add(item.name);
    }

    // Convert the Set to an array of objects suitable for a dropdown
    let dropdownData = Array.from(uniqueNames).map(name => ({ value: name, label: name }));

    return dropdownData;
}
