import { ReleaseTable } from './ReleaseTable';
import { ExtensionTable } from './ExtensionTable';
import { useToolkitReleases } from './data';
import { useFeature } from '@gsm-app/hooks/useFeature';

export function NGTAppManager() {
    const { data, isFetching } = useToolkitReleases();
    const { adminPageV2 } = useFeature();
    return (
        <div style={adminPageV2 ? { display: 'flex', flexDirection: 'column', flex: 1 } : undefined}>
            {!adminPageV2 && <ReleaseTable releases={data || []} isFetchingReleases={isFetching} />}
            <ExtensionTable releases={data || []} />
        </div>
    );
}
