import { useModalOnClose } from '@gsm-app/hooks/useModalOnClose';
import {
    Button,
    ButtonGroup,
    Dropdown,
    type DropdownOption,
    Heading,
    Input,
    Modal,
    ModalBody,
    ModalFooter,
    ModalHeader,
    Stack,
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { type ChangeEvent, useEffect, useState } from 'react';
import type { NewAssetDetails } from './types';

type PlatformOptionType = DropdownOption<string>;

interface AddAssetModalProps {
    platformOptions: PlatformOptionType[];
    name: string;
    version: string;
    show: boolean;
    upload?: boolean;
    onClose: () => void;
    onAdd: (asset: NewAssetDetails) => void;
}

export function NewAssetModal({ platformOptions, name, version, show, upload, onClose, onAdd }: AddAssetModalProps) {
    const [selectedAssetPlatform, setSelectedAssetPlatform] = useState<PlatformOptionType | null>(null);
    const [assetHash, setAssetHash] = useState<string>('');
    const [assetBin, setAssetBin] = useState<string>('');
    const [assetPath, setAssetPath] = useState<string>('');
    const [assetUrl, setAssetUrl] = useState<string>('');
    const [selectedFile, setSelectedFile] = useState<File>();
    const [isFormIneractedWith, setIsFormIneractedWith] = useState(false);
    const [validationErrors, setValidationErrors] = useState<{ [id: string]: string | null }>({
        assetArchive: null,
        assetPlatform: null,
        assetBin: null,
    });

    useEffect(() => {
        if (selectedAssetPlatform && selectedFile) {
            const newAssetPath = `${name}/${selectedAssetPlatform.value}/versions/${version}/${selectedFile.name}`;
            setAssetPath(newAssetPath);
        }
    }, [selectedAssetPlatform, selectedFile]);

    useEffect(() => {
        if (isFormIneractedWith) {
            validateForm();
        }
    }, [selectedAssetPlatform, selectedFile, assetBin, isFormIneractedWith]);

    function handlePlatformChange(selectedOption: PlatformOptionType | null) {
        setSelectedAssetPlatform(selectedOption);
        setIsFormIneractedWith(true);
    }

    function handleFileChange(event: ChangeEvent<HTMLInputElement>) {
        if (event.target.files) {
            setSelectedFile(event.target.files[0]);
            setIsFormIneractedWith(true);
        }
    }

    function handleAssetUrlChange(event: ChangeEvent<HTMLInputElement>) {
        setAssetUrl(event.target.value);
        setIsFormIneractedWith(true);
    }

    function handleAssetBinPathChange(event: ChangeEvent<HTMLInputElement>) {
        setAssetBin(event.target.value);
        setIsFormIneractedWith(true);
    }

    function handleAssetHashChange(event: ChangeEvent<HTMLInputElement>) {
        setAssetHash(event.target.value);
        setIsFormIneractedWith(true);
    }

    function handleCloseClick() {
        resetForm();
        onClose();
    }

    async function handleUploadClick() {
        if (!validateForm()) {
            return;
        }

        const newAsset = {
            name,
            version,
            hash: assetHash,
            platform: selectedAssetPlatform!.value,
            bin: assetBin,
            file: selectedFile!,
        };

        onAdd(newAsset);
        resetForm();
    }

    function resetForm() {
        setSelectedAssetPlatform(null);
        setAssetHash('');
        setAssetBin('');
        setAssetPath('');
        setSelectedFile(undefined);
        setIsFormIneractedWith(false);
        setValidationErrors({
            assetArchive: null,
            assetPlatform: null,
            assetBin: null,
        });
    }

    function validateForm() {
        let errors = {
            assetPlatform: selectedAssetPlatform?.value ? null : 'A platform is required.',
            assetArchive: selectedFile ? null : 'An archive is required.',
            assetBin: assetBin ? null : 'A path to the bin is required.',
        };
        setValidationErrors(errors);
        return !Object.values(errors).some(error => error !== null);
    }

    const fileSizeInMb = selectedFile?.size ? Math.round(selectedFile.size / (1024 * 1024)) : undefined;

    const handleOnClose = useModalOnClose({ onClose });

    return (
        <Modal style={{ width: '600px' }} maxWidth='medium' open={show} onClose={handleOnClose}>
            <ModalHeader>
                <Heading level={0}>New Asset</Heading>
            </ModalHeader>
            <ModalBody>
                <Stack gap={Dimensions.Space6}>
                    <Input label='Name' readOnly value={name} />
                    <Input label='Version' readOnly value={version} />
                    <Input label='Hash' value={assetHash} onChange={handleAssetHashChange} />
                    {upload ? (
                        <Input
                            label='Archive File'
                            id='assetArchive'
                            type='file'
                            requirementType='required-star'
                            onChange={handleFileChange}
                            validationMessage={validationErrors.assetArchive}
                            validationStatus={validationErrors.assetArchive ? 'error' : undefined}
                        />
                    ) : (
                        <Input
                            label='Archive Url'
                            id='assetArchiveUrl'
                            requirementType='required-star'
                            value={assetUrl}
                            onChange={handleAssetUrlChange}
                            validationMessage={validationErrors.assetArchive}
                            validationStatus={validationErrors.assetArchive ? 'error' : undefined}
                        />
                    )}
                    <Dropdown
                        label='Target Platform'
                        id='assetPlatform'
                        placeholder='Select the platform'
                        requirementType='required-star'
                        options={platformOptions}
                        value={selectedAssetPlatform}
                        onChange={handlePlatformChange}
                        validationMessage={validationErrors.assetPlatform}
                        validationStatus={validationErrors.assetPlatform ? 'error' : undefined}
                    />
                    <Input
                        label='Bin Path'
                        id='assetBin'
                        requirementType='required-star'
                        onChange={handleAssetBinPathChange}
                        validationMessage={validationErrors.assetBin}
                        validationStatus={validationErrors.assetBin ? 'error' : undefined}
                    />
                    <Input label='Destination Path' value={assetPath} readOnly tabIndex={-1} />
                    <Input label='Size (MB)' readOnly value={fileSizeInMb?.toString() || 'N/A'} />
                </Stack>
            </ModalBody>
            <ModalFooter>
                <ButtonGroup justifyContent='flex-end'>
                    <Button variant='secondary' onClick={handleCloseClick}>
                        Close
                    </Button>
                    <Button onClick={handleUploadClick}>Upload</Button>
                </ButtonGroup>
            </ModalFooter>
        </Modal>
    );
}
