import { useModalOnClose } from '@gsm-app/hooks/useModalOnClose';
import {
    Button,
    ButtonGroup,
    Dropdown,
    type DropdownOption,
    FormGroup,
    Heading,
    InlineFeedback,
    Input,
    Modal,
    ModalBody,
    ModalFooter,
    ModalHeader,
} from '@hawkins/components';
import { type ChangeEvent, useEffect, useState } from 'react';
import { AssetTable } from './AssetTable';
import { AssignedReleasesTable } from './AssignedReleasesTable';
import type { ToolkitAsset, ToolkitExtension, ToolkitRelease } from './types';
import { useFeature } from '@gsm-app/hooks/useFeature';

type ExtensionOptionType = DropdownOption<string>;

interface UploadExtensionModalProps {
    releases: ToolkitRelease[];
    extensionOptions: ExtensionOptionType[];
    show: boolean;
    currentExtension: ToolkitExtension;
    onClose: () => void;
    onUpdate: (extension: ToolkitExtension) => void;
}

export function EditExtensionModal({
    releases,
    extensionOptions,
    show,
    onClose,
    onUpdate,
    currentExtension,
}: UploadExtensionModalProps) {
    const { adminPageV2 } = useFeature();
    const [selectedExtensionName, setSelectedExtensionName] = useState<ExtensionOptionType | null>({
        value: currentExtension?.name,
        label: currentExtension?.name,
    });
    const [extensionVersion, setExtensionVersion] = useState<string>(currentExtension?.version);
    const [assets, setAssets] = useState<ToolkitAsset[]>(currentExtension.assets);
    const [assignedReleases, setAssignedReleases] = useState<ToolkitRelease[]>(currentExtension.releases);
    const [isFormIneractedWith, setIsFormIneractedWith] = useState<boolean>(false);
    const [validationErrors, setValidationErrors] = useState<{ [id: string]: string | null }>({
        extensionName: null,
        extensionVersion: null,
        addedAssets: null,
        assignedReleases: null,
    });

    useEffect(() => {
        if (isFormIneractedWith) {
            validateForm();
        }
    }, [selectedExtensionName, extensionVersion, isFormIneractedWith]);

    function handleAddAsset(asset: ToolkitAsset) {
        setAssets(prevAssets => [...prevAssets, asset]);
    }

    function handleDeleteAsset(asset: ToolkitAsset) {
        setAssets(prevAssets => prevAssets.filter(prevAsset => prevAsset.uuid !== asset.uuid));
    }

    function handleUpdateAsset(asset: ToolkitAsset) {
        setAssets(prevAssets => prevAssets.map(prevAsset => prevAsset.uuid === asset.uuid ? asset : prevAsset));
    }

    function validateForm(keys?: string[]) {
        let errors: any = {
            extensionName: selectedExtensionName?.value
                ? null
                : 'Please provide a name for the extension. This field is required.',
            extensionVersion: extensionVersion
                ? null
                : 'Please specify a version number for the extension. This field is required.',
            assets: assets.length ? null : 'Please add at least one asset. Assets cannot be left empty.',
            assignedReleases: adminPageV2 ? null : (assignedReleases.length
                ? null
                : 'The extension must be assigned to at least one release. Please assign a release.'),
        };
        let keysToValidate = keys ?? Object.keys(errors);
        let filteredErrors = keysToValidate.reduce((acc, key) => {
            if (key in errors) {
                acc[key] = errors[key];
            }
            return acc;
        }, {} as any);

        setValidationErrors(filteredErrors);
        return !Object.values(filteredErrors).some(error => error !== null);
    }

    function handleExtensionNameChange(selectedOption: ExtensionOptionType | null) {
        setSelectedExtensionName(selectedOption);
        setIsFormIneractedWith(true);
    }

    function handleExtensionVersionChange(event: ChangeEvent<HTMLInputElement>) {
        setExtensionVersion(event.target.value);
        setIsFormIneractedWith(true);
    }

    function handleCloseClick() {
        onClose();
    }

    function handleAssignRelease(release: ToolkitRelease) {
        setAssignedReleases(prevState => (prevState ? [...prevState, release] : [release]));
    }

    async function handleSaveClick() {
        if (!validateForm()) {
            return;
        }

        const updatedExtension = {
            uuid: currentExtension.uuid,
            name: selectedExtensionName!.value,
            version: extensionVersion,
            assets,
            releases: assignedReleases,
        };

        onUpdate(updatedExtension);
    }

    function handleValidationErrorsFeedbackClose() {
        let resetErrors: any = {};
        for (let key in validationErrors) {
            resetErrors[key] = null;
        }
        setValidationErrors(resetErrors);
    }

    const errorList = Object.values(validationErrors)
        .filter(error => !!error)
        .map((error, index) => <li key={index}>{error}</li>);

    const releasesWithAssign = releases.map(release => {
        const isAssigned = assignedReleases.some(assignedRelease => assignedRelease.uuid === release.uuid);

        if (isAssigned) {
            return { ...release, assignToRelease: true };
        } else {
            return release;
        }
    });

    const handleOnClose = useModalOnClose({ onClose });

    return (
        <Modal fullScreen open={show} onClose={handleOnClose}>
            <ModalHeader>
                <Heading level={0}>Edit Extension</Heading>
            </ModalHeader>
            <ModalBody>
                {errorList.length ? (
                    <InlineFeedback
                        message={<ul>{errorList}</ul>}
                        variant='error'
                        dismissible
                        onClose={handleValidationErrorsFeedbackClose}
                    />
                ) : null}
                <FormGroup>
                    <FormGroup>
                        <Dropdown
                            label='Name'
                            id='extensionName'
                            placeholder='Select or add an extension'
                            requirementType='required-star'
                            options={extensionOptions}
                            onChange={handleExtensionNameChange}
                            value={selectedExtensionName}
                            creatable
                            searchable
                            showRecentlySelected
                        />
                        <Input
                            label='Version'
                            id='extensionVersion'
                            requirementType='required-star'
                            placeholder='Type a version'
                            value={extensionVersion}
                            onChange={handleExtensionVersionChange}
                            inputProps={{
                                pattern: '[A-Za-z0-9._-]',
                                autoComplete: 'off',
                                max: 50,
                            }}
                        />
                        <AssetTable
                            upload={true}
                            assets={assets}
                            name={selectedExtensionName?.value!}
                            version={extensionVersion}
                            onValidateForm={keys => validateForm(keys)}
                            onAdd={handleAddAsset}
                            onDelete={handleDeleteAsset}
                            onUpdate={handleUpdateAsset}
                        />
                        {!adminPageV2 && <AssignedReleasesTable releases={releasesWithAssign} onAssignRelease={handleAssignRelease} />}
                    </FormGroup>
                </FormGroup>
            </ModalBody>
            <ModalFooter>
                <ButtonGroup justifyContent='flex-end'>
                    <Button variant='secondary' onClick={handleCloseClick}>
                        Close
                    </Button>
                    <Button onClick={handleSaveClick}>Save</Button>
                </ButtonGroup>
            </ModalFooter>
        </Modal>
    );
}
