import {
    AllCommunityModule,
    type ColDef,
    type ColGroupDef,
    type ICellRendererParams,
} from 'ag-grid-community';
import {
    ColumnsToolPanelModule,
    FiltersToolPanelModule,
    MenuModule,
    SetFilterModule,
    SideBarModule,
} from 'ag-grid-enterprise';

import {
    type Notification,
    type NotificationTarget,
    useNotifications
} from '@gsm-app/hooks/useNotifications';
import { useTelemetry } from '@ui-paved-road/telemetry/react';
import { IconMenu, IconPencil, IconPlus, IconTrashCan } from '@hawkins/assets';
import { Badge, Button, Menu, MenuItem, Stack, Text } from '@hawkins/components';
import { TableNext } from '@hawkins/table-next';

import { Dimensions } from '@hawkins/variables';
import { useQueryClient } from '@tanstack/react-query';
import { useCallback, useMemo } from 'react';
import { PAGINATION_OPTIONS, PAGINATION_PAGE_SIZE } from '@gsm-app/constants';

interface NotificationsTableProps {
    onAddNotification: () => void;
    onEditNotification: (notification: Notification) => void;
    onDeleteNotification: (Notification: Notification) => void;
}

export function NotificationsTable(props: NotificationsTableProps) {
    const { onAddNotification, onEditNotification, onDeleteNotification } = props;
    const queryClient = useQueryClient();
    const { data } = useNotifications({ all: true });
    const notifications = data || [];
    const telemetry = useTelemetry();
    telemetry.setLoggingTag('ncgtportal', 'NotificationsTable');

    const onEdit = useCallback((data: Notification) => {
        onEditNotification(data);
    }, [onEditNotification]);

    const onDelete = useCallback((data: Notification) => {
        onDeleteNotification(data);
        queryClient.invalidateQueries({ queryKey: ['notifications'] });
    }, [onDeleteNotification, queryClient.invalidateQueries]);

    const modules = useMemo(
        () => [
            AllCommunityModule,
            SetFilterModule,
            MenuModule,
            SideBarModule,
            ColumnsToolPanelModule,
            FiltersToolPanelModule,
        ],
        [],
    );

    const columnDefs = useMemo<(ColDef<Notification> | ColGroupDef<Notification>)[]>(() => {
        return [
            {
                field: 'title',
                headerName: 'Title',
                filter: 'agTextColumnFilter',
            },
            {
                field: 'markup',
                headerName: 'Markup',
                filter: 'agTextColumnFilter',
            },
            {
                field: 'variant',
                headerName: 'Type',
                maxWidth: Dimensions.RawSize224,
                cellRenderer: (params: ICellRendererParams<Notification, string>) => {
                    let color = 'UNKNOWN';
                    switch (params.value) {
                        case 'REGULAR':
                            color = 'Gray';
                            break;
                        case 'ERROR':
                            color = 'FAILURE';
                            break;
                        case 'SUCCESS':
                            color = 'COMPLETE';
                            break;
                        case 'WARNING':
                            color = 'IN_PROGRESS';
                            break;
                        default:
                            color = 'UNKNOWN';
                            break;
                    }

                    return (
                        <Badge color={color}>{params.value}</Badge>
                    );
                },
            },
            {
                field: 'target',
                filter: 'agTextColumnFilter',
                headerName: 'Target',
                cellRenderer: (params: ICellRendererParams<Notification, string>) => {
                    try {
                        const targetData: NotificationTarget | undefined = params.value as NotificationTarget | undefined;
                        return targetData ? JSON.stringify(targetData, null, 2) : '';
                    } catch (error) {
                        telemetry.logger.error(`Error parsing target JSON data: ${error}`);
                        return '';
                    }
                }
            },
            {
                field: 'createdBy',
                filter: 'agTextColumnFilter',
                headerName: 'Creator',
            },
            {
                field: 'updatedBy',
                filter: 'agTextColumnFilter',
                headerName: 'Updated',
            },
            {
                field: 'startDate',
                filter: 'agDateColumnFilter',
                headerName: 'Start Date',
            },
            {
                field: 'endDate',
                filter: 'agDateColumnFilter',
                headerName: 'End Date',
            },
            {
                headerName: '',
                sortable: false,
                filter: false,
                maxWidth: Dimensions.RawSize56,
                suppressHeaderMenuButton: true,
                suppressHeaderContextMenu: true,
                cellStyle: {
                    overflow: 'hidden',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                },
                cellRenderer: (params: ICellRendererParams<Notification>) => {
                    if (!params.data) {
                        return;
                    }
                    return (
                        <Menu trigger={
                            <Button variant='icon' compact icon={IconMenu} aria-label='trigger' />
                        }>
                            <MenuItem key='edit' label='Edit' icon={IconPencil} onClick={() => onEdit(params.data!)} />
                            <MenuItem key='delete' label='Delete' icon={IconTrashCan} onClick={() => onDelete(params.data!)} />
                        </Menu>
                    )
                },
            },

        ];

    }, [telemetry, onEdit, onDelete]);

    const defaultColDef = useMemo<ColDef>(() => {
        return {
            editable: false,
            filter: true,
            floatingFilter: true,
            minWidth: 100,
            resizable: true,
            sortable: true,
        };
    }, []);

    const autoGroupColumnDef = useMemo<ColDef>(() => {
        return {
            cellRendererParams: {
                checkbox: false,
                suppressCount: false,
            },
            headerName: 'Group',
            menuTabs: [],
            minWidth: 250,
        };
    }, []);

    const isLoading = !notifications;

    return (
        <Stack
            gap={Dimensions.Space4}
            layout={{
                display: 'flex',
                flex: 1,
                alignItems: 'start',
                flexDirection: 'column'
            }} style={{
                marginTop: Dimensions.Space10
            }}
        >
            <Button compact icon={IconPlus} onClick={onAddNotification}>
                New Notification
            </Button>
            <TableNext<Notification>
                animateRows={true}
                loading={isLoading}
                autoGroupColumnDef={autoGroupColumnDef}
                columnDefs={columnDefs}
                enableCellTextSelection={true}
                noRowsOverlayComponent={() => <Text>No notifications available</Text>}
                ensureDomOrder={true}
                defaultColDef={defaultColDef}
                groupDefaultExpanded={1}
                modules={modules}
                pagination={true}
                paginationPageSize={PAGINATION_PAGE_SIZE}
                paginationPageSizeSelector={PAGINATION_OPTIONS}
                rowData={notifications}
                style={{ height: '100%', width: '100%' }}
            />
        </Stack>
    );
}
