interface AssetUploadResponse {
    url: string;
}

async function uploadAsset({
    asset,
    onProgress,
}: {
    asset: NewAssetDetails;
    onProgress?: (p: number) => void;
    onSuccess?: ({ url }: { url: string }) => void;
}) {
    const { file, name, version, platform } = asset;
    return await axios.post<AssetUploadResponse>(`/api/toolkit/assets/upload`, file, {
        headers: {
            'Content-Type': 'application/x-gzip',
            'X-Ncgt-Toolkit-Asset-Name': name,
            'X-Ncgt-Toolkit-Asset-Filename': file.name,
            'X-Ncgt-Toolkit-Asset-Version': version,
            'X-Ncgt-Toolkit-Asset-Platform': platform,
        },
        maxContentLength: Infinity,
        maxBodyLength: Infinity,
        onUploadProgress: (evt: AxiosProgressEvent) => {
            const p = evt.total ? Math.round((evt.loaded / evt.total) * 100) : 0;
            if (!isNaN(p) && onProgress) {
                onProgress(p);
            }
        },
    });
}

async function deleteAsset(asset: ToolkitAsset) {
    return await axios.delete(`/api/toolkit/assets/${asset.uuid}`);
}

