// Hooks

export function useToolkitReleases() {
    const query = useQuery({
        queryKey: ['toolkit-releases'],
        queryFn: fetchReleases,
    });

    const { error, isError } = query;
    useEffect(() => {
        if (isError) {
            createError({
                title: 'Error Loading Releases',
                body: `${error?.message}`,
                options: {
                    id: 'toolkit-releases-fetch-error',
                },
            });
        }
    }, [error, isError, createError]);

    return query;
}

