export function useToolkitReleaseCreate() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: createRelease,
        // When mutate is called:
        onMutate: async (newRelease) => {
            // Cancel any outgoing refetches
            // (so they don't overwrite our optimistic update)
            await queryClient.cancelQueries({ queryKey: ['toolkit-releases'] });

            // Snapshot the previous value
            const previousReleases = queryClient.getQueryData(['toolkit-releases']);

            // Optimistically update to the new value
            queryClient.setQueryData(['toolkit-releases'], (old: ToolkitRelease[] | undefined) => {
                return [...old!, newRelease];
            });

            // Return a context object with the snapshotted value
            return { previousReleases };
        },
        // If the mutation fails,
        // use the context returned from onMutate to roll back
        onError: (err: Error, newRelease, context) => {
            queryClient.setQueryData(['toolkit-releases'], context?.previousReleases);
            createError({
                title: 'Error Creating Release',
                body: `${err?.message}`,
                options: {
                    id: 'toolkit-releases-create-error',
                },
            });
        },
        // Always refetch after error or success:
        onSettled: () => {
            queryClient.invalidateQueries({ queryKey: ['toolkit-releases'] });
        },
    });
}

export function useToolkitReleaseUpdate() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: updateRelease,
        // When mutate is called:
        onMutate: async (newRelease) => {
            // Cancel any outgoing refetches
            // (so they don't overwrite our optimistic update)
            await queryClient.cancelQueries({ queryKey: ['toolkit-releases', newRelease.uuid] });

            // Snapshot the previous value
            const previousRelease = queryClient.getQueryData(['toolkit-releases', newRelease.uuid]);

            // Optimistically update to the new value
            queryClient.setQueryData(['toolkit-releases', newRelease.uuid], newRelease);

            // Return a context with the previous and new todo
            return { previousRelease, newRelease };
        },
        // If the mutation fails, use the context we returned above
        onError: (err: Error, newRelease, context) => {
            queryClient.setQueryData(['toolkit-releases', context?.newRelease.uuid], context?.previousRelease);
            createError({
                title: 'Error Updating Release',
                body: `${err?.message}`,
                options: {
                    id: 'toolkit-releases-update-error',
                },
            });
        },
        // Always refetch after error or success:
        onSettled: (newRelease) => {
            queryClient.invalidateQueries({ queryKey: ['toolkit-releases', newRelease?.uuid] });
        },
    });
}

export function useToolkitReleaseDelete() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: deleteRelease,
        onSettled: () => {
            queryClient.invalidateQueries({ queryKey: ['toolkit-releases'] });
        },
    });
}

export function useToolkitAssetUpload() {
    return useMutation({
        mutationFn: uploadAsset,
        onSuccess: (data, variables) => {
            if (variables.onSuccess) {
                variables.onSuccess({
                    url: data.data.url,
                });
            }
        },
    });
}

