import { IconMenu, IconPencil, IconPlus, IconTrashCan } from '@hawkins/assets';
import { Button, MenuItem, Stack } from '@hawkins/components';
import {
    BadgeRenderer,
    DatePickerEditor,
    DropdownEditor,
    DropdownFilter,
    HawkinsTableClassNames,
    MenuRenderer,
    Table,
    TextFilter,
    Toolbar,
    type TypeColumn,
    type TypeEditInfo,
} from '@hawkins/table';
import { Dimensions } from '@hawkins/variables';
import { useCallback, useState } from 'react';
import { NewReleaseModal } from './NewReleaseModal';
import {
    useToolkitReleaseChannels,
    useToolkitReleaseCreate,
    useToolkitReleaseDelete,
    useToolkitReleaseUpdate,
} from './data';
import type { ToolkitRelease } from './types';

export enum ToolkitReleaseState {
    DRAFT = 'DRAFT',
    SCHEDULED = 'SCHEDULED',
    PUBLISHED = 'PUBLISHED',
}

const releaseStateOptions = Object.values(ToolkitReleaseState).map(state => ({ value: state, label: state }));

const renderReleaseDetails = ({ data }: { data: ToolkitRelease }) => {
    return (
        <div style={{ padding: 20 }}>
            <h3>Release details:</h3>
            <table>
                <tbody>
                    {Object.keys(data).map((name, i) => {
                        let value = data[name];
                        if (Array.isArray(value)) {
                            if (value.every(item => typeof item === 'object')) {
                                // This is an array of objects. We'll represent each object with its JSON string.
                                if (name === 'assets') {
                                    // If this is the assets array, display the platform names in bullet point form
                                    value = value
                                        .map(item => item.platform && item.platform.name)
                                        .filter(Boolean)
                                        .map(platformName => <li key={platformName}>{platformName}</li>);
                                    value = <ul>{value}</ul>;
                                } else if (name === 'extensions') {
                                    value = value
                                        .map(item => ({ name: item.name, version: item.version, state: item.state }))
                                        .filter(Boolean)
                                        .map(extension => (
                                            <li key={extension.version}>
                                                {extension.name}@{extension.version} [{extension.state}]
                                            </li>
                                        ));
                                    value = <ul>{value}</ul>;
                                } else {
                                    value = value.map(item => JSON.stringify(item)).join(', ');
                                }
                            } else {
                                // This is an array of primitive values (numbers, strings, etc).
                                value = value.join(', ');
                            }
                        } else if (typeof value === 'object' && value !== null) {
                            // This is a single object.
                            if (name === 'channel') {
                                value = value.displayName;
                            } else {
                                value = JSON.stringify(value);
                            }
                        }
                        return (
                            <tr key={i}>
                                <td>{name}</td>
                                <td>{value}</td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
        </div>
    );
};

interface ReleaseTableProps {
    releases: ToolkitRelease[];
    isFetchingReleases: boolean;
}

export function ReleaseTable({ releases, isFetchingReleases }: ReleaseTableProps) {
    const [showAddReleaseModal, setShowAddReleaseModal] = useState(false);
    const [expandedRows, setExpandedRows] = useState<{ [key: string]: boolean } | undefined>(undefined);
    const [collapsedRows, setCollapsedRows] = useState<{ [key: string]: boolean } | undefined>(undefined);
    const { data: channels = [], isFetching: isFetchingChannels } = useToolkitReleaseChannels();
    const { mutate: releaseCreate, isPending: isCreatingRelease } = useToolkitReleaseCreate();
    const { mutate: releaseUpdate, isPending: isUpdatingRelease } = useToolkitReleaseUpdate();
    const { mutate: releaseDelete, isPending: isDeletingRelease } = useToolkitReleaseDelete();

    const channelOptions = channels.map(ch => ({ value: ch.name, label: ch.displayName }));

    const releaseColumns: TypeColumn[] = [
        {
            name: 'channel',
            header: 'Channel',
            textAlign: 'center',
            flex: 1,
            render: ({ data }: { data: ToolkitRelease }) => data.channel.displayName,
            filterEditor: DropdownFilter({
                placeholder: 'Filter by channel...',
                options: channelOptions,
            }),
        },
        {
            name: 'version',
            header: 'Version',
            textAlign: 'center',
            flex: 1,
            filterEditor: TextFilter({
                placeholder: 'Filter by version...',
            }),
        },
        {
            name: 'state',
            header: 'State',
            textAlign: 'center',
            flex: 1,
            editable: true,
            render: BadgeRenderer<string, ToolkitRelease>({
                badgeProps: ({ value }) => {
                    if (value === ToolkitReleaseState.PUBLISHED) {
                        return {
                            color: 'COMPLETE',
                        };
                    } else if (value === ToolkitReleaseState.DRAFT) {
                        return {
                            color: 'IN_PROGRESS',
                        };
                    } else {
                        return {
                            color: 'UNKNOWN',
                        };
                    }
                },
            }),
            renderEditor: DropdownEditor({
                compact: true,
                dropdownProps: {
                    clearable: false,
                },
                options: releaseStateOptions,
            }),
            filterEditor: DropdownFilter({
                placeholder: 'Filter by state...',
                options: releaseStateOptions,
            }),
        },
        {
            name: 'publishedDate',
            header: 'Published Date',
            textAlign: 'center',
            flex: 1,
            render: ({ data }: { data: ToolkitRelease }) =>
                data.publishedDate ? new Date(data.publishedDate).toLocaleString() : '',
        },
        {
            name: 'releaseScheduleDate',
            header: 'Release Schedule Date',
            textAlign: 'center',
            flex: 1,
            editable: (editValue, cellProps) => cellProps.data.state === ToolkitReleaseState.SCHEDULED,
            className: ({ data }: { data: ToolkitRelease }) =>
                data.state === ToolkitReleaseState.SCHEDULED && !data.releaseScheduleDate
                    ? HawkinsTableClassNames.ValidationError
                    : '',
            render: ({ data }: { data: ToolkitRelease }) =>
                data.releaseScheduleDate ? new Date(data.releaseScheduleDate).toLocaleString() : '',
            renderEditor: DatePickerEditor({
                compact: true,
                calendarProps: { pickerVariant: 'datetimepicker' },
            }),
        },
        // {
        //     name: 'createdDate',
        //     header: 'Created Date',
        //     textAlign: 'center',
        //     flex: 1,
        //     render: ({ data }: { data: ToolkitRelease }) => data.createdDate ? new Date(data.createdDate).toLocaleString() : ''
        // },
        {
            name: 'actions',
            textAlign: 'center',
            flex: 1,
            render: MenuRenderer<string, ToolkitRelease>({
                trigger: <Button variant='icon' compact icon={IconMenu} aria-label='trigger' />,
                menuItems: ({ data }) => {
                    return [
                        <MenuItem key='edit' label='Edit' icon={IconPencil} onClick={() => handleEditClick(data)} />,
                        <MenuItem
                            key='delete'
                            label='Delete'
                            icon={IconTrashCan}
                            onClick={() => handleDeleteClick(data)}
                        />,
                    ];
                },
            }),
        },
    ];

    function handleAddReleaseClick() {
        setShowAddReleaseModal(true);
    }

    function handleAddReleaseModalClose() {
        setShowAddReleaseModal(false);
    }

    function handleCreateRelease(data: ToolkitRelease) {
        setShowAddReleaseModal(false);
        releaseCreate(data);
    }

    function handleEditClick(release: ToolkitRelease) {}

    function handleDeleteClick(release: ToolkitRelease) {
        releaseDelete(release);
    }

    const onExpandedRowsChange = useCallback(
        ({ expandedRows, collapsedRows }: { expandedRows: any; collapsedRows: any }) => {
            setExpandedRows(expandedRows);
            setCollapsedRows(collapsedRows);
        },
        [],
    );

    const onEditComplete = useCallback(
        async ({ value, columnId, rowIndex }: TypeEditInfo) => {
            const data = [...releases];
            data[rowIndex][columnId] = value;
            releaseUpdate(data[rowIndex]);
        },
        [releases],
    );

    const isLoading =
        isFetchingReleases || isFetchingChannels || isCreatingRelease || isUpdatingRelease || isDeletingRelease;

    return (
        <div style={{ marginTop: '10px' }}>
            <Table<ToolkitRelease>
                loading={isLoading}
                disableTableHeaderTooltip
                rowHeight='compact'
                idProperty='uuid'
                columns={releaseColumns}
                dataSource={releases}
                onEditComplete={onEditComplete}
                expandedRows={expandedRows}
                collapsedRows={collapsedRows}
                // @ts-expect-error
                onExpandedRowsChange={onExpandedRowsChange}
                rowExpandHeight={400}
                // @ts-expect-error
                renderRowDetails={renderReleaseDetails}
                style={{ width: '100%', minHeight: 500 }}
                defaultFilterValue={[
                    { name: 'version', operator: 'contains', type: 'string', value: null },
                    { name: 'channel', operator: 'inlist', type: 'select', value: null },
                    { name: 'state', operator: 'inlist', type: 'select', value: null },
                ]}
            >
                <Toolbar
                    left={
                        <Stack gap={Dimensions.Space10} orientation='horizontal'>
                            <Button compact icon={IconPlus} onClick={handleAddReleaseClick}>
                                New Release
                            </Button>
                        </Stack>
                    }
                />
            </Table>
            <NewReleaseModal
                channelOptions={channelOptions}
                show={showAddReleaseModal}
                onClose={handleAddReleaseModalClose}
                onCreate={handleCreateRelease}
            />
        </div>
    );
}
