import type { Notification } from '@gsm-app/hooks/useNotifications';
import { useQueryClient } from '@tanstack/react-query';
import { useCallback, useState } from 'react';
import { NotificationsTable } from '../NCGTAppManager/NotificationsTable';
import { NewNotificationModal } from '../NotificationsModal/NewNotificationModal';

export function NotificationsManager() {
    const [showNewNotificationModal, setShowNewNotificationModal] = useState(false);
    const [notification, setNotification] = useState<Notification | undefined>();
    const queryClient = useQueryClient();

    const onAddNotification = useCallback(() => {
        setShowNewNotificationModal(true);
        setNotification(undefined);
    }, []);

    const onClose = useCallback(() => {
        setShowNewNotificationModal(false);
        setNotification(undefined);
    }, []);

    const onCreate = useCallback(async (data: Notification) => {
        setShowNewNotificationModal(false);
        setNotification(undefined);

        const response = await fetch('/api/notifications', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(data),
        }).then(response => response.json());

        queryClient.invalidateQueries({ queryKey: ['notifications'] });

        return response;
    }, [queryClient.invalidateQueries]);

    const onEditNotification = useCallback((notification: Notification) => {
        setNotification(notification);
    }, []);

    const onEdit = useCallback(async (notification: Notification) => {
        setShowNewNotificationModal(false);
        setNotification(undefined);
        const response = await fetch(`/api/notifications/${notification.uuid}`, {
            method: 'PATCH',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(notification),
        }).then(response => response.json());

        queryClient.invalidateQueries({ queryKey: ['notifications'] });

        return response;
    }, [queryClient.invalidateQueries]);

    const onDelete = useCallback(async (notification: Notification) => {
        const response = await fetch(`/api/notifications/${notification.uuid}`, {
            method: 'DELETE',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(notification),
        });
        queryClient.invalidateQueries({ queryKey: ['notifications'] });

        return response;
    }, [queryClient.invalidateQueries]);

    return (
        <>
            <NotificationsTable
                onAddNotification={onAddNotification}
                onEditNotification={onEditNotification}
                onDeleteNotification={onDelete}
            />
            <NewNotificationModal
                show={showNewNotificationModal || !!notification}
                notification={notification}
                onClose={onClose}
                onCreate={onCreate}
                onEdit={onEdit}
            />
        </>
    );
}
