import {
    BadgeRenderer,
    CheckboxEditor,
    CheckboxRenderer,
    DropdownFilter,
    Table,
    TextFilter,
    type TypeColumn,
    type TypeEditInfo,
} from '@hawkins/table';
import { useCallback, useEffect, useState } from 'react';
import { ToolkitReleaseState } from './ReleaseTable';
import type { ToolkitExtension, ToolkitRelease } from './types';

interface AssignedReleasesTableProps {
    releases: ToolkitRelease[];
    onAssignRelease: (release: ToolkitRelease) => void;
}

const releaseStateOptions = Object.values(ToolkitReleaseState).map(state => ({ value: state, label: state }));

export function AssignedReleasesTable({ releases, onAssignRelease }: AssignedReleasesTableProps) {
    const [assignedReleases, setAssignedReleases] = useState(releases);

    useEffect(() => {
        setAssignedReleases(releases);
    }, [releases]);

    const releasesColumns: TypeColumn[] = [
        {
            name: 'version',
            header: 'Release Version',
            flex: 1,
            filterEditor: TextFilter({
                placeholder: 'Filter by version...',
            }),
        },
        {
            name: 'channel',
            header: 'Release Channel',
            flex: 1,
            render: ({ data }: { data: ToolkitRelease }) => data.channel.name,
        },
        {
            name: 'state',
            header: 'Release State',
            textAlign: 'center',
            flex: 1,
            render: BadgeRenderer<string, ToolkitExtension>({
                badgeProps: ({ value }) => {
                    if (value === ToolkitReleaseState.PUBLISHED) {
                        return {
                            color: 'COMPLETE',
                        };
                    } else if (value === ToolkitReleaseState.DRAFT) {
                        return {
                            color: 'IN_PROGRESS',
                        };
                    } else {
                        return {
                            color: 'UNKNOWN',
                        };
                    }
                },
            }),
            filterEditor: DropdownFilter({
                placeholder: 'Filter by state...',
                options: releaseStateOptions,
            }),
        },
        {
            name: 'publishedDate',
            header: 'Published Date',
            flex: 1,
        },
        {
            name: 'assignToRelease',
            header: 'Assign To Release',
            flex: 1,
            render: CheckboxRenderer<boolean>(),
            renderEditor: CheckboxEditor(),
        },
    ];

    const onEditComplete = useCallback(
        ({ value, columnId, rowIndex }: TypeEditInfo) => {
            const data = [...assignedReleases];
            data[rowIndex][columnId] = value;
            setAssignedReleases(data);
            onAssignRelease(data[rowIndex]);
        },
        [assignedReleases],
    );

    return (
        <Table
            disableTableHeaderTooltip
            rowHeight='compact'
            idProperty='uuid'
            editable
            columns={releasesColumns}
            dataSource={assignedReleases}
            onEditComplete={onEditComplete}
            style={{ width: '100%' }}
            defaultFilterValue={[
                { name: 'version', operator: 'contains', type: 'string', value: null },
                { name: 'state', operator: 'inlist', type: 'select', value: null },
            ]}
        />
    );
}
