import { NotificationsManager } from '@gsm-app/components/NotificationsManager/NotificationsManager';
import { Content } from '@gsm-common/components/Content';
import { Layout } from '@gsm-common/components/Layout';
import { useSearchParams } from '@gsm-common/hooks/useSearchParams';
import { Heading, Tab, TabList, TabPanel, TabPanelItem, TabbedInterface } from '@hawkins/components';
import { NGTAppManager } from '../../components/NCGTAppManager';
import { useFeature } from '@gsm-app/hooks/useFeature';

const NCGT_APP = 'ncgt-app';
const NOTIFICATIONS = 'notifications';

export const Admin = () => {
    const { adminPageV2 } = useFeature();
    const [params, setParams] = useSearchParams<{ t: string | undefined }>({
        t: NCGT_APP,
    });
    return (
        <Layout full>
            <Content style={{display: 'flex', flexDirection: 'column'}}>
                <Heading level={2}>Admin</Heading>
                <TabbedInterface layout={{
                    display: 'flex',
                    flex: 1,
                    flexDirection: 'column'
                }}>
                    <TabList
                        value={params.t}
                        onChange={value => {
                            setParams(() => ({ t: value }));
                        }}
                    >
                        <Tab value={NCGT_APP}>{adminPageV2 ? 'Toolkit Extensions' : 'NCGT App'}</Tab>
                        <Tab value={NOTIFICATIONS}>Notifications</Tab>
                    </TabList>

                    <TabPanel layout={{
                    display: 'flex',
                    flex: 1,
                    flexDirection: 'column'
                }}>
                        <TabPanelItem value={NCGT_APP}>
                            <NGTAppManager />
                        </TabPanelItem>
                        <TabPanelItem value={NOTIFICATIONS}>
                            <NotificationsManager />
                        </TabPanelItem>
                    </TabPanel>
                </TabbedInterface>
            </Content>
        </Layout>
    );
};
